import json
import os
import sys

FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
}


def format_date(val):
    if not val or not isinstance(val, str):
        return None
    val = val.strip()
    if not val or val.upper() == "N/A":
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    parts = val.split("-")
    if (
        len(parts) == 3
        and len(parts[0]) == 4
        and len(parts[1]) == 2
        and len(parts[2]) == 2
    ):
        return val
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    data_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_entity = {}

    if os.path.exists(data_file):
        with open(data_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_entity.setdefault(recall_num, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        pair_results = {}

        records = records_by_entity.get(entity, [])

        for fact_name in fact_names:
            field_name = FACT_FIELD_MAP.get(
                fact_name, fact_name.replace(" ", "_")
            )
            is_date = "date" in fact_name or "date" in field_name

            values = set()
            for rec in records:
                raw_val = rec.get(field_name)
                if is_date:
                    val = format_date(raw_val)
                else:
                    if raw_val is not None and str(raw_val).strip() != "":
                        val = str(raw_val).strip()
                    else:
                        val = None

                if val is not None:
                    values.add(val)

            if not values:
                pair_results[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_results[fact_name] = "CONFLICT"
            else:
                pair_results[fact_name] = [
                    next(iter(values)),
                    "fda_enforcement_reports",
                ]

        output[pair] = pair_results

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

