import json
import os
import sys

FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
}


def format_value(field_name, val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        if not val or val.upper() == "N/A":
            return None
        if "date" in field_name:
            if len(val) == 8 and val.isdigit():
                return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    doc_name = "fda_enforcement_reports"
    doc_file = os.path.join(packet_dir, f"{doc_name}.json")

    records = []
    if os.path.exists(doc_file):
        with open(doc_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            if isinstance(data, dict) and "results" in data:
                records = data["results"]
            elif isinstance(data, list):
                records = data

    # Index records by recall_number
    records_by_recall = {}
    for r in records:
        rn = r.get("recall_number")
        if rn:
            records_by_recall.setdefault(rn, []).append(r)

    facts_spec = manifest.get("facts", {})
    pairs = manifest.get("pairs", [])

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        needed_facts = facts_spec.get(rule_id, [])

        matching_records = records_by_recall.get(entity, [])

        entity_facts = {}
        for fact_name in needed_facts:
            field_name = FACT_FIELD_MAP.get(fact_name)
            if not field_name:
                field_name = fact_name.replace(" ", "_")

            values = []
            for r in matching_records:
                raw_val = r.get(field_name)
                val = format_value(field_name, raw_val)
                if val is not None:
                    values.append(val)

            distinct_vals = list(dict.fromkeys(values))

            if len(distinct_vals) == 0:
                entity_facts[fact_name] = "ABSENT"
            elif len(distinct_vals) == 1:
                entity_facts[fact_name] = [distinct_vals[0], doc_name]
            else:
                entity_facts[fact_name] = "CONFLICT"

        output[pair] = entity_facts

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

