import json
import os
import sys

RULE_FIELD_MAP = {
    ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
    ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
    ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
    ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
}


def format_date(val: str) -> str:
    val = val.strip()
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    enforcement_reports_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}

    if os.path.exists(enforcement_reports_path):
        with open(enforcement_reports_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", []) if isinstance(data, dict) else data
            for record in results:
                recall_num = record.get("recall_number")
                if recall_num:
                    records_by_recall_number.setdefault(recall_num.strip(), []).append(record)

    output = {}

    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])

        entity_clean = entity.strip()
        matching_records = records_by_recall_number.get(entity_clean, [])

        pair_result = {}
        for fact_name in facts:
            mapping = RULE_FIELD_MAP.get((rule_id, fact_name))
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping
            values = set()

            for rec in matching_records:
                raw_val = rec.get(field_name)
                if raw_val is not None:
                    raw_val = str(raw_val).strip()
                    if raw_val:
                        formatted = format_date(raw_val)
                        values.add(formatted)

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [next(iter(values)), doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

