            "termination date": (doc_name, "termination_date"),
        },
    }

    generic_fact_fields = {
        "initiation date": (doc_name, "recall_initiation_date"),
        "classification date": (doc_name, "center_classification_date"),
        "termination date": (doc_name, "termination_date"),
    }

    records_by_recall_number = {}
    for record in fda_records:
        rec_num = record.get("recall_number")
        if rec_num:
            rec_num_clean = str(rec_num).strip()
            records_by_recall_number.setdefault(rec_num_clean, []).append(record)

    out = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        entity_id_clean = entity_id.strip()
        matching_records = records_by_recall_number.get(entity_id_clean, [])

        pair_facts = facts_schema.get(rule_id, [])
        pair_result = {}

