            if rule_id in rule_fact_fields and fact_name in rule_fact_fields[rule_id]:
                target_doc, target_field = rule_fact_fields[rule_id][fact_name]
            elif fact_name in generic_fact_fields:
                target_doc, target_field = generic_fact_fields[fact_name]

            if not target_field or not matching_records:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_values = set()
            for rec in matching_records:
                raw_val = rec.get(target_field)
                parsed_val = parse_date(raw_val)
                if parsed_val:
                    extracted_values.add(parsed_val)

            if len(extracted_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(extracted_values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [next(iter(extracted_values)), target_doc]

        out[pair] = pair_result

    print(json.dumps(out, indent=2))

if __name__ == "__main__":
    main()

