import json
import os
import sys

FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
}

DOC_NAME = "fda_enforcement_reports"


def format_date(val):
    if not val or not isinstance(val, str):
        return None
    val = val.strip()
    if not val or val.upper() in ("N/A", "NONE", "NULL"):
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if len(val) == 10 and val[4] == "-" and val[7] == "-":
        return val
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, f"{DOC_NAME}.json")
    records_by_recall = {}

    if os.path.exists(reports_path):
        with open(reports_path, "r", encoding="utf-8") as f:
            data = json.load(f)

        if isinstance(data, dict) and "results" in data:
            results = data["results"]
        elif isinstance(data, list):
            results = data
        else:
            results = []

        for item in results:
            if isinstance(item, dict):
                r_num = item.get("recall_number")
                if r_num:
                    r_num_clean = str(r_num).strip()
                    records_by_recall.setdefault(r_num_clean, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_def = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        entity_clean = entity.strip()
        pair_facts = facts_def.get(rule_id, [])

        pair_result = {}
        matched_records = records_by_recall.get(entity_clean, [])

        for fact_name in pair_facts:
            field_name = FACT_FIELD_MAP.get(fact_name)
            if not field_name:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_values = set()
            for record in matched_records:
                raw_val = record.get(field_name)
                formatted_val = format_date(raw_val)
                if formatted_val is not None:
                    extracted_values.add(formatted_val)

            if len(extracted_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(extracted_values) == 1:
                val = next(iter(extracted_values))
                pair_result[fact_name] = [val, DOC_NAME]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))


if __name__ == "__main__":
    main()

